// C++ offers multiple initialization syntaxes
int x(0);        // Initialization with parentheses (direct-initialization)
int y = 0;       // Initialization with equals (copy-initialization)
int z{ 0 };      // Initialization with braces (direct-list-initialization)
int w = { 0 };   // Initialization with equals and braces (copy-list-initialization)

// C++ generally treats {0} and = {0} identically.
// The key distinction to master is between using () and {}.
